def pair_features(p,x,r,a):
 s,H=state(p,x);count=s[5];scalar=np.array([s[0],s[1],max(0,s[3]/count-(s[2]/count)**2),s[4]/count]);hr=p['H'][r];ha=p['H'][a];hn=np.linalg.norm(H);rn=np.linalg.norm(hr,axis=1);an=np.linalg.norm(ha,axis=1);dr=hr@H;da=ha@H;change=ha-hr
 direction=np.column_stack((np.full(len(r),hn),dr,da,dr/(hn*rn+1e-30),da/(hn*an+1e-30),np.sum(hr*ha,axis=1)/(rn*an+1e-30),np.linalg.norm(H+change,axis=1)-hn,change@H/(np.linalg.norm(change,axis=1)*hn+1e-30)))
 return np.column_stack((p['page'][r],p['page'][a],np.broadcast_to(scalar,(len(r),4)),direction))
