def ranking_metrics(gain,j,oracle):
 positive=np.maximum(gain,0);best=np.maximum(oracle,0);relative=gain/j;oracle_rel=best/j
 return dict(n=len(j),mean_gain_pct=float(relative.mean()*100),median_gain_pct=float(np.median(relative)*100),p10_gain_pct=float(np.quantile(relative,.1)*100),worst_gain_pct=float(relative.min()*100),degraded=int((gain< -1e-12).sum()),positive=int((gain>1e-12).sum()),positive_filtered_mean_pct=float(np.mean(positive/j)*100),oracle_mean_pct=float(oracle_rel.mean()*100),positive_filtered_recovery=float(np.mean(positive/j)/np.mean(oracle_rel)) if np.mean(oracle_rel)>1e-12 else None,actual_recovery=float(np.mean(relative)/np.mean(oracle_rel)) if np.mean(oracle_rel)>1e-12 else None)
